params.command:
$ErrorActionPreference='Stop';
$repo='C:\Users\Xxkan\actions-runner-heaven\_work\mhw-mods\mhw-mods';
if (-not (Test-Path (Join-Path $repo '.git'))) { throw 'canonical checkout unavailable' }
Set-Location $repo;
git fetch origin main integration/hcp-index-wiring-v040-20260929;
if ($LASTEXITCODE -ne 0) { throw 'git fetch failed' }
$remoteHead=(git rev-parse origin/integration/hcp-index-wiring-v040-20260929).Trim();
if ($remoteHead -ne '58ddc0059c74c07da8c53d4a2fa88fdb60520371') { throw "branch head moved: $remoteHead" }
$wt=Join-Path $env:TEMP 'mhw-hcp-v040-58ddc005';
if (Test-Path $wt) { git worktree remove --force $wt 2>$null; if (Test-Path $wt) { Remove-Item -LiteralPath $wt -Recurse -Force } }
git worktree add --detach $wt $remoteHead;
if ($LASTEXITCODE -ne 0) { throw 'git worktree add failed' }
try {
  Set-Location $wt;
  python -m py_compile heaven-bridge/worker.py heaven-bridge/test_worker.py heaven-bridge/tests/test_worker.py;
  if ($LASTEXITCODE -ne 0) { throw 'bridge compile failed' }
  python -m compileall -q plugins/heaven-control-plane/heaven_control_plane plugins/heaven-control-plane/tests plugins/heaven-control-plane/verify.py;
  if ($LASTEXITCODE -ne 0) { throw 'control-plane compile failed' }
  python heaven-bridge/test_worker.py;
  if ($LASTEXITCODE -ne 0) { throw 'primary bridge tests failed' }
  python heaven-bridge/tests/test_worker.py;
  if ($LASTEXITCODE -ne 0) { throw 'compat bridge tests failed' }
  python plugins/heaven-control-plane/verify.py;
  if ($LASTEXITCODE -ne 0) { throw 'control-plane verify failed' }
  $base=(git merge-base origin/main HEAD).Trim();
  git diff --check $base HEAD;
  if ($LASTEXITCODE -ne 0) { throw 'git diff --check failed' }
  [pscustomobject]@{
    verified_head=(git rev-parse HEAD);
    merge_base=$base;
    origin_main=(git rev-parse origin/main);
    result='PASS'
  } | ConvertTo-Json -Compress
}
finally {
  Set-Location $repo;
  git worktree remove --force $wt 2>$null
}
